/**
 * Deliberate faults for the bundled reference server. Each one breaks exactly one
 * conformance rule, so `statelint demo` and the tests can show what each failure looks like.
 */
export const FAULT_IDS = [
    "requires-initialize",
    "no-discover",
    "mints-session-id",
    "rejects-unknown-session",
    "get-opens-stream",
    "delete-accepted",
    "initialize-silent",
    "version-header-optional",
    "version-header-unchecked",
    "method-header-optional",
    "method-header-unchecked",
    "method-header-case-insensitive",
    "name-header-optional",
    "name-header-unchecked",
    "name-header-no-base64",
    "draft-error-code",
    "x-mcp-header-on-number",
    "x-mcp-header-secret",
    "unsupported-version-no-list",
    "meta-optional",
    "unknown-method-200",
    "error-id-null",
    "legacy-not-found-code",
    "no-result-type",
    "no-cache-hints",
    "no-server-info",
    "unstable-tools-order",
    "wrong-content-type",
    "sse-duplicate-response",
    "sse-server-request",
    "sse-unrequested-log",
    "sse-stays-open",
    "sse-buffered",
    "listen-no-ack",
    "accepts-any-origin",
];
export const FAULTS = [
    { id: "requires-initialize", rule: "no-handshake", base: "json", summary: "a 2025-11-25 server: demands initialize and an Mcp-Session-Id before anything else" },
    { id: "no-discover", rule: "server-discover", base: "json", summary: "answers server/discover with 404 Method not found" },
    { id: "mints-session-id", rule: "no-session-id", base: "json", summary: "puts an Mcp-Session-Id header on every response" },
    { id: "rejects-unknown-session", rule: "session-id-ignored", base: "json", summary: "answers 404 Session not found when a request carries an old Mcp-Session-Id" },
    { id: "get-opens-stream", rule: "legacy-methods-405", base: "json", summary: "still opens the 2025-era standalone SSE stream on GET" },
    { id: "delete-accepted", rule: "legacy-methods-405", base: "json", summary: "still accepts DELETE for session termination" },
    { id: "initialize-silent", rule: "initialize-names-versions", base: "json", summary: "rejects a legacy initialize without saying which versions it supports" },
    { id: "version-header-optional", rule: "version-header-required", base: "json", summary: "serves a request that has no MCP-Protocol-Version header" },
    { id: "version-header-unchecked", rule: "version-header-match", base: "json", summary: "never compares MCP-Protocol-Version with the _meta protocolVersion" },
    { id: "method-header-optional", rule: "method-header-required", base: "json", summary: "serves a request that has no Mcp-Method header" },
    { id: "method-header-unchecked", rule: "method-header-match", base: "json", summary: "routes on the body and ignores a contradicting Mcp-Method header" },
    { id: "method-header-case-insensitive", rule: "method-header-match", base: "json", summary: "compares Mcp-Method case-insensitively" },
    { id: "name-header-optional", rule: "name-header-required", base: "json", summary: "serves tools/call, resources/read and prompts/get without Mcp-Name" },
    { id: "name-header-unchecked", rule: "name-header-match", base: "json", summary: "never compares Mcp-Name with params.name or params.uri" },
    { id: "name-header-no-base64", rule: "name-header-base64", base: "json", summary: "compares Mcp-Name without decoding the =?base64?…?= sentinel" },
    { id: "draft-error-code", rule: "header-error-code", base: "json", summary: "rejects header mismatches with the pre-release draft code -32001 instead of -32020" },
    { id: "x-mcp-header-on-number", rule: "x-mcp-header-valid", base: "json", summary: "lists a tool that puts x-mcp-header on a number parameter" },
    { id: "x-mcp-header-secret", rule: "x-mcp-header-no-secrets", base: "json", summary: "mirrors an apiKey argument into a Mcp-Param-Api-Key header" },
    { id: "unsupported-version-no-list", rule: "unsupported-version", base: "json", summary: "rejects an unknown version without data.supported" },
    { id: "meta-optional", rule: "meta-required", base: "json", summary: "serves a request whose _meta has no clientCapabilities" },
    { id: "unknown-method-200", rule: "unknown-method-404", base: "json", summary: "answers an unknown method with HTTP 200 and an in-band -32601" },
    { id: "error-id-null", rule: "error-id-echo", base: "json", summary: "sends every error response with id null" },
    { id: "legacy-not-found-code", rule: "resource-not-found-code", base: "json", summary: "answers a missing resource with the retired code -32002" },
    { id: "no-result-type", rule: "result-type", base: "json", summary: "leaves resultType out of every result" },
    { id: "no-cache-hints", rule: "cache-hints", base: "json", summary: "leaves ttlMs and cacheScope out of discover and list results" },
    { id: "no-server-info", rule: "server-info", base: "json", summary: "never identifies itself in result _meta" },
    { id: "unstable-tools-order", rule: "tools-order", base: "json", summary: "returns tools/list in a different order on every other call" },
    { id: "wrong-content-type", rule: "response-content-type", base: "json", summary: "sends JSON bodies as Content-Type: text/plain" },
    { id: "sse-duplicate-response", rule: "sse-single-response", base: "sse", summary: "sends the final response twice on the SSE stream" },
    { id: "sse-server-request", rule: "sse-no-server-requests", base: "sse", summary: "sends an elicitation/create request on a response stream" },
    { id: "sse-unrequested-log", rule: "sse-no-unrequested-logs", base: "sse", summary: "emits notifications/message although the request set no logLevel" },
    { id: "sse-stays-open", rule: "sse-closes", base: "sse", summary: "keeps the SSE stream open after the final response" },
    { id: "sse-buffered", rule: "sse-x-accel-buffering", base: "sse", summary: "starts SSE streams without X-Accel-Buffering: no" },
    { id: "listen-no-ack", rule: "subscriptions-listen", base: "json", summary: "starts a subscriptions/listen stream without the acknowledgment" },
    { id: "accepts-any-origin", rule: "origin-validation", base: "json", summary: "serves requests from any Origin" },
];
export function faultInfo(id) {
    return FAULTS.find((f) => f.id === id);
}
export function isFaultId(id) {
    return FAULT_IDS.includes(id);
}
